window.installOnlineBridge=function(T,a){
  const peers=new Map(),clone=v=>JSON.parse(JSON.stringify(v));let backup=null;
  const chapterDefaults={picnicReady:false,picnicPrepared:false,invited:[],basket:false,served:[],groceries:[],vegDelivered:false,bileFound:false,ballFound:false,ballReturned:false,signalChecked:false,spring:false,summer:false,autumn:false,winter:false,clues:[],passageOpen:false,rescued:false};
  function clean(data){const s=a.defaults();for(const key of Object.keys(s))if(data&&Object.hasOwn(data,key))s[key]=data[key];s.step=Math.max(0,Math.min(26,Math.floor(Number(s.step)||0)));for(const key of ['money','energy','health','hunger','x','z','bikeDistance','deliveries','time'])s[key]=Number.isFinite(Number(s[key]))?Number(s[key]):a.defaults()[key];s.health=Math.max(0,Math.min(100,s.health));s.hunger=Math.max(0,Math.min(100,s.hunger));s.money=Math.max(0,Math.min(99999,s.money));s.chapter2={...chapterDefaults};for(const key of Object.keys(chapterDefaults)){const v=data?.chapter2?.[key];if(Array.isArray(chapterDefaults[key]))s.chapter2[key]=Array.isArray(v)?v.filter(x=>typeof x==='string').slice(0,10):[];else s.chapter2[key]=v===true;}
    for(const key of ['trash','tasted','picnicGiven'])if(!Array.isArray(s[key]))s[key]=[];s.inTunnel=data?.inTunnel===true;s.season=['primavera','verao','outono','inverno'].includes(data?.season)?data.season:'primavera';s.rainManual=null;return s;}
  function avatar(p,profile){p.shirt.color.set(profile.color||'#e97843');p.skinMat.color.set(profile.skin||'#bd916f');p.hairMat.color.set(profile.hair||'#382e24');}
  function restore(data){const v=clean(data),x=v.x,z=v.z;a.setState(v);a.level2.setInside(v.inTunnel);a.player.g.position.set(Math.max(-140,Math.min(140,x)),.31,Math.max(-140,Math.min(140,z)));v.x=x;v.z=z;a.clearInput();a.syncWorld();}
  const bridge={
    started:a.started,
    setProfile(profile){const s=a.getState();s.name=profile.display_name;s.color=profile.color;if(backup){backup.name=s.name;backup.color=s.color;}avatar(a.player,profile);a.updateHUD();},
    account(profile,saved){backup=null;a.setCoop(false);a.setSaveKey(a.saveKey+'-'+profile.id);restore(saved);bridge.setProfile(profile);a.start();a.save();},
    guest(){backup=null;a.setCoop(false);a.setSaveKey(null);let saved;try{saved=JSON.parse(localStorage.getItem(a.saveKey));}catch{}restore(saved);avatar(a.player,{color:a.getState().color});a.updateHUD();},
    snapshot(){return clone(a.getState());},
    group(shared){if(!backup){backup=clone(a.getState());a.setCoop(true);const s=clean({name:backup.name,color:backup.color,health:backup.health,hunger:backup.hunger,x:backup.x,z:backup.z});a.setState(s);a.level2.setInside(false);a.player.g.position.set(0,.31,65);}const s=a.getState();const allowed=['step','money','carrying','invitation','trash','photos','deliveries','delivery','treeCleared','treePaid','treeDelivered','chopRemaining','tasted','picnicStarted','picnicGiven','chapter2'];const normalized=clean(shared);for(const key of allowed)s[key]=normalized[key];if(shared.cutAt){s.chopRemaining=Math.max(0,(shared.cutAt-Date.now())/1000);s.treeCleared=s.chopRemaining===0;}if(s.inTunnel&&s.chapter2.rescued)a.level2.setInside(false);a.syncWorld();},
    leaveGroup(){if(backup){const saved=backup;backup=null;a.setCoop(false);restore(saved);a.save();}},
    effect(effect){if(!effect)return;const s=a.getState();if(effect.food){s.hunger=Math.min(100,s.hunger+effect.food);if(s.hunger===100)s.fullFor=40;}if(effect.bike)a.adventure.setTransport('bike');if(typeof effect.tunnel==='boolean')a.level2.setInside(effect.tunnel);a.updateHUD();},
    pose(){const p=a.player.g.position,s=a.getState();return {x:p.x,y:p.y,z:p.z,yaw:a.player.g.rotation.y,inTunnel:!!s.inTunnel,transport:s.transport,bikeDistance:s.bikeDistance,step:s.step};},
    peer(id,profile,pose){let peer=peers.get(id);if(!peer){const p=a.person(profile.color,profile.skin);avatar(p,profile);a.scene.add(p.g);const tag=a.label(profile.display_name,0,3,65);tag.remote=true;const item={id:'remote-'+id,onlineId:id,type:'remote-player',name:profile.display_name,x:0,z:65,radius:3,p};a.interactables.push(item);peer={p,tag,item,target:new T.Vector3(0,.31,65),yaw:0,inTunnel:false,profile};p.g.position.copy(peer.target);peers.set(id,peer);}if(pose){if(!['x','y','z','yaw'].every(k=>Number.isFinite(pose[k])))return;if(Math.abs(pose.x)>145||Math.abs(pose.z)>145||pose.y<0||pose.y>12)return;peer.target.set(pose.x,pose.y,pose.z);peer.yaw=pose.yaw;peer.inTunnel=pose.inTunnel===true;}peer.profile=profile;avatar(peer.p,profile);peer.tag.el.textContent=profile.display_name;peer.item.name=profile.display_name;},
    removePeer(id){const p=peers.get(id);if(!p)return;a.scene.remove(p.p.g);p.tag.el.remove();a.labels.splice(a.labels.indexOf(p.tag),1);a.interactables.splice(a.interactables.indexOf(p.item),1);p.p.g.traverse(o=>{if(o.geometry&&o.geometry!==a.unitBox)o.geometry.dispose();});p.p.shirt.dispose();p.p.skinMat.dispose();p.p.hairMat.dispose();peers.delete(id);},
    tick(dt,t){for(const p of peers.values()){const visible=p.inTunnel===!!a.getState().inTunnel;p.p.g.visible=visible;p.tag.forceHidden=!visible;const moving=p.p.g.position.distanceTo(p.target)>.05;p.p.g.position.lerp(p.target,1-Math.exp(-dt*12));const delta=Math.atan2(Math.sin(p.yaw-p.p.g.rotation.y),Math.cos(p.yaw-p.p.g.rotation.y));p.p.g.rotation.y+=delta*Math.min(1,dt*12);a.animatePerson(p.p,moving,t);p.tag.pos.copy(p.p.g.position).add(new T.Vector3(0,2.8,0));p.item.x=p.p.g.position.x;p.item.z=p.p.g.position.z;p.item.tunnel=p.inTunnel;}window.CerroOnline?.frame(t);},
    toast:a.toast,clearInput:a.clearInput
  };return bridge;
};
